import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ __launch_bounds__(256, 8) void tanh_kernel_vec4(const float4* __restrict__ in, float4* __restrict__ out, int64_t n4) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    int64_t i = idx;
    // Unrolled by 2 to balance ILP with register pressure, improving occupancy
    for (; i + stride < n4; i += 2 * stride) {
        float4 v0 = in[i];
        float4 v1 = in[i + stride];
        float4 r0, r1;
        r0.x = tanhf(v0.x); r0.y = tanhf(v0.y); r0.z = tanhf(v0.z); r0.w = tanhf(v0.w);
        r1.x = tanhf(v1.x); r1.y = tanhf(v1.y); r1.z = tanhf(v1.z); r1.w = tanhf(v1.w);
        out[i] = r0;
        out[i + stride] = r1;
    }
    for (; i < n4; i += stride) {
        float4 v = in[i];
        float4 r;
        r.x = tanhf(v.x);
        r.y = tanhf(v.y);
        r.z = tanhf(v.z);
        r.w = tanhf(v.w);
        out[i] = r;
    }
}
__global__ __launch_bounds__(256, 8) void tanh_kernel_scalar(const float* __restrict__ in, float* __restrict__ out, int64_t n) {
    int64_t idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;
    int64_t i = idx;
    for (; i + stride < n; i += 2 * stride) {
        float v0 = in[i];
        float v1 = in[i + stride];
        out[i] = tanhf(v0);
        out[i + stride] = tanhf(v1);
    }
    for (; i < n; i += stride) {
        out[i] = tanhf(in[i]);
    }
}
torch::Tensor tanh_cuda(torch::Tensor x) {
    auto x_contig = x.contiguous();
    auto out = torch::empty_like(x_contig);
    int64_t n = x_contig.numel();

    const int threads = 256;

    if (n % 4 == 0) {
        int64_t n4 = n / 4;
        int blocks = (int)((n4 + threads - 1) / threads);
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        tanh_kernel_vec4<<<blocks, threads>>>(
            reinterpret_cast<const float4*>(x_contig.data_ptr<float>()),
            reinterpret_cast<float4*>(out.data_ptr<float>()),
            n4
        );
    } else {
        int blocks = (int)((n + threads - 1) / threads);
        if (blocks > 65535) blocks = 65535;
        if (blocks < 1) blocks = 1;
        tanh_kernel_scalar<<<blocks, threads>>>(
            x_contig.data_ptr<float>(),
            out.data_ptr<float>(),
            n
        );
    }

    return out;
}
"""

cpp_source = "torch::Tensor tanh_cuda(torch::Tensor x);"

tanh_module = load_inline(
    name="tanh_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["tanh_cuda"],
    extra_cuda_cflags=["-use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a Tanh activation using a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.tanh_op = tanh_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.tanh_op.tanh_cuda(x)


